import{_ as e,o as i,c as n,ae as a}from"./chunks/framework.Bs_1Tt6f.js";const g=JSON.parse('{"title":"Manuscript Annotation (Polygon Editor)","description":"","frontmatter":{},"headers":[],"relativePath":"docs/annotation.md","filePath":"docs/annotation.md"}'),o={name:"docs/annotation.md"};function r(s,t,l,c,d,p){return i(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="manuscript-annotation-polygon-editor" tabindex="-1">Manuscript Annotation (Polygon Editor) <a class="header-anchor" href="#manuscript-annotation-polygon-editor" aria-label="Permalink to &quot;Manuscript Annotation (Polygon Editor)&quot;">​</a></h1><p>The core visual feature of the tool is the <strong>Polygon Editor</strong>. This interface allows you to draw shapes directly onto high-resolution manuscript scans and link them to your transcription data.</p><h2 id="setting-up-a-manuscript" tabindex="-1">Setting up a Manuscript <a class="header-anchor" href="#setting-up-a-manuscript" aria-label="Permalink to &quot;Setting up a Manuscript&quot;">​</a></h2><p>Before you can annotate, you need to add a manuscript to your workspace.</p><ol><li>Navigate to the <strong>Manuscript Annotations</strong> view.</li><li>Click <strong>Add Manuscript</strong>.</li><li>Provide a short, recognizable name (e.g., &quot;St. Gallen 359&quot;) and a unique system identifier.</li><li><strong>Crucially</strong>, provide the valid <strong>IIIF Manifest URL</strong> for the manuscript.</li><li>The tool will parse the manifest and load the image viewer.</li></ol><div class="info custom-block"><p class="custom-block-title">💡 Suggestion for Future Documentation</p><p><em>[Consider inserting a brief screen recording here demonstrating how to find a IIIF Manifest URL on a library site (like Gallica or e-codices) and pasting it into the application.]</em></p></div><h2 id="drawing-line-regions" tabindex="-1">Drawing Line Regions <a class="header-anchor" href="#drawing-line-regions" aria-label="Permalink to &quot;Drawing Line Regions&quot;">​</a></h2><p>Annotations are organized by &quot;Lines&quot;. Before drawing individual neumes, you must define the staff lines on the page.</p><ol><li>Open a specific folio/page from the manuscript.</li><li>In the toolbar, ensure the <strong>Line Region</strong> tool is selected (often represented by a rectangle icon).</li><li>Click and drag a box around a complete line of music and text.</li><li>A prompt will appear asking you to name the region. Use a standard convention (e.g., &quot;Line 1&quot;, &quot;Line 2&quot;).</li><li>Repeat this for all lines on the page you wish to annotate.</li></ol><h2 id="annotating-specific-signs" tabindex="-1">Annotating Specific Signs <a class="header-anchor" href="#annotating-specific-signs" aria-label="Permalink to &quot;Annotating Specific Signs&quot;">​</a></h2><p>Once lines are defined, you can annotate individual graphical shapes (neumes).</p><ol><li>Select a Line Region you created.</li><li>Switch to the <strong>Polygon</strong> drawing tool in the toolbar.</li><li>Click to drop points around the perimeter of the specific neume you want to capture. Close the shape by clicking the first point again.</li></ol><div class="info custom-block"><p class="custom-block-title">💡 Suggestion for Future Documentation</p><p><em>[Consider inserting an animated GIF or short video here showing the precise click-by-click process of drawing a polygon around a complex neume shape.]</em></p></div><ol start="4"><li>The <strong>Transcription Linking</strong> panel will open.</li><li>The panel displays occurrences from your transcription data that are mapped to this manuscript.</li><li>Select the exact occurrence that corresponds to the shape you just drew.</li></ol><h2 id="handling-variants" tabindex="-1">Handling Variants <a class="header-anchor" href="#handling-variants" aria-label="Permalink to &quot;Handling Variants&quot;">​</a></h2><p>If the shape you drew is a slight variation of its standard Ref ID (e.g., it&#39;s a <code>10</code> but written with a distinct flourish), you can specify a variant.</p><ul><li>In the linking panel, there is a field for <strong>Variant Suffix</strong>.</li><li>Enter your suffix (e.g., <code>a</code>, <code>b</code>, <code>*</code>).</li><li>If your transcription data already contains variant suffixes (e.g., <code>10b</code>), the tool will attempt to extract and apply it automatically when you link the occurrence.</li></ul>',17)])])}const h=e(o,[["render",r]]);export{g as __pageData,h as default};
